const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const spaw = @import("spawn"); const regi = @import("registry"); const supe = @import("tasksuper"); const prob = @import("taskprobe"); const conf = @import("store"); const stre = @import("stream");
const tktickbase = @import("tk-tick-base.zig"); const ArmeReje = tktickbase.ArmeReje; const CF = tktickbase.CF; const CatcReqz = tktickbase.CatcReqz; const ChaiFini = tktickbase.ChaiFini; const ChaiRunz = tktickbase.ChaiRunz; const ChaiView = tktickbase.ChaiView; const Jobz = tktickbase.Jobz; const PollReqz = tktickbase.PollReqz; const RunzLast = tktickbase.RunzLast; const RunzLastReco = tktickbase.RunzLastReco; const RunzResu = tktickbase.RunzResu; const RunzSlot = tktickbase.RunzSlot; const StarReqz = tktickbase.StarReqz; const chaiResu = tktickbase.chaiResu; const finiPush = tktickbase.finiPush; const intoDupe = tktickbase.intoDupe; const jobzClon = tktickbase.jobzClon; const jobzFill = tktickbase.jobzFill; const logzDirz = tktickbase.logzDirz; const logzRota = tktickbase.logzRota; const membNext = tktickbase.membNext; const nowzMsec = tktickbase.nowzMsec; const plusPick = tktickbase.plusPick; const poolCoun = tktickbase.poolCoun; const poolPick = tktickbase.poolPick; const recoLast = tktickbase.recoLast; const ringDrop = tktickbase.ringDrop; const ringNote = tktickbase.ringNote; const ringSeal = tktickbase.ringSeal; const taskFind = tktickbase.taskFind;
const Sche = @import("tk-task-tick.zig").Sche;
pub fn jobzFree(self: *Sche, jobz: *Jobz) void { if (jobz.teez) |teez| teez.rele(); self.gpaz.destroy(jobz); }
pub fn disp(self: *Sche, iozz: std.Io, jobz_list: []Jobz) void { for (jobz_list) |*jobz| { if (jobz.once_stam.len > 0 or jobz.catc) { var temp = std.heap.ArenaAllocator.init(self.gpaz); defer temp.deinit(); if (jobz.once_stam.len > 0) stor.onceFireMark(temp.allocator(), iozz, jobz.iden, jobz.once_stam); if (jobz.catc) stor.fireLastWrit(temp.allocator(), iozz, jobz.iden, time.localNow().minute_stamp); } const pntr = jobzClon(self.gpaz, jobz) catch { if (jobz.teez) |teez| { ringSeal(iozz, teez, -1, 0); teez.rele(); } continue; }; if (!self.queuEnqu(iozz, pntr)) { if (pntr.teez) |teez| ringSeal(iozz, teez, -1, 0); self.jobzFree(pntr); } } }
pub fn queuEnqu(self: *Sche, iozz: std.Io, pntr: *Jobz) bool { { self.queu_mute.lock(iozz) catch return false; defer self.queu_mute.unlock(iozz); if (self.queu.items.len >= CF.queu_maxz) return false; if (self.runnLockIszz(pntr.iden)) return false; for (self.queu.items) |item| if (std.mem.eql(u8, item.iden, pntr.iden)) return false; self.queu.append(self.gpaz, pntr) catch return false; } self.workWake(iozz); return true; }
pub fn queuRequ(self: *Sche, iozz: std.Io, pntr: *Jobz) void { { self.queu_mute.lock(iozz) catch { self.gpaz.destroy(pntr); return; }; defer self.queu_mute.unlock(iozz); self.queu.append(self.gpaz, pntr) catch { self.gpaz.destroy(pntr); return; }; } self.workWake(iozz); }
pub fn workWake(self: *Sche, iozz: std.Io) void { { self.queu_mute.lock(iozz) catch return; defer self.queu_mute.unlock(iozz); if (self.queu_work >= conf.tune.workers) return; if (self.queu_work >= self.queu.items.len) return; self.queu_work += 1; } const thre = std.Thread.spawn(.{}, workMain, .{ self, iozz }) catch { self.queu_mute.lock(iozz) catch return; self.queu_work -= 1; self.queu_mute.unlock(iozz); return; }; thre.detach(); }
pub fn runnLockIszz(self: *Sche, iden: []const u8) bool { for (&self.runn) |*slot| if (slot.acti and std.mem.eql(u8, slot.iden(), iden)) return true; return false; }
pub fn lockHeldIszz(self: *Sche, lock: []const u8) bool { if (std.mem.eql(u8, lock, "none")) return false; for (&self.runn) |*slot| if (slot.acti and std.mem.eql(u8, slot.lockName(), lock)) return true; return false; }
pub fn lockPick(self: *Sche, nowz: i64) ?*Jobz { var indx: usize = 0; while (indx < self.queu.items.len) : (indx += 1) { const jobz = self.queu.items[indx]; if (jobz.notz_befo_msec > nowz) continue; if (self.runnLockIszz(jobz.iden)) continue; if (self.lockHeldIszz(jobz.lock)) continue; return self.queu.orderedRemove(indx); } return null; }
pub fn workMain(self: *Sche, iozz: std.Io) void { while (true) { var jobz_valu: ?*Jobz = null; var slot_indx: usize = 0; { self.queu_mute.lock(iozz) catch return; defer self.queu_mute.unlock(iozz); if (self.queu.items.len == 0 or self.stop.load(.acquire)) { self.queu_work -= 1; return; } if (self.lockPick(nowzMsec(iozz))) |pick| { slot_indx = for (&self.runn, 0..) |*item, indx| { if (!item.acti) break indx; } else 0; const slot = &self.runn[slot_indx]; slot.* = .{ .acti = true, .sinc_msec = nowzMsec(iozz) }; slot.iden_leng = intoDupe(&slot.iden_buff, pick.iden).len; slot.lock_leng = intoDupe(&slot.lock_buff, pick.lock).len; jobz_valu = pick; } else if (self.queu_work > 1) { self.queu_work -= 1; return; } } const jobz = jobz_valu orelse { std.Io.sleep(iozz, .fromMilliseconds(CF.work_wait_msec), .awake) catch return; continue; }; const requ = self.jobzExec(iozz, jobz); { self.queu_mute.lock(iozz) catch return; self.runn[slot_indx].acti = false; self.queu_mute.unlock(iozz); } if (!requ) self.jobzFree(jobz); self.workWake(iozz); } }
pub fn queuWrit(self: *Sche, iozz: std.Io, wrtr: *std.Io.Writer) !void { const nowz = nowzMsec(iozz); try self.queu_mute.lock(iozz); defer self.queu_mute.unlock(iozz); try wrtr.writeAll("{\"running\":["); var firs = true; for (&self.runn) |*slot| { if (!slot.acti) continue; if (!firs) try wrtr.writeAll(","); firs = false; try wrtr.writeAll("{\"id\":"); try std.json.Stringify.encodeJsonString(slot.iden(), .{}, wrtr); try wrtr.writeAll(",\"lock\":"); try std.json.Stringify.encodeJsonString(slot.lockName(), .{}, wrtr); try wrtr.print(",\"sinceMin\":{d}}}", .{@divTrunc(nowz - slot.sinc_msec, 60_000)}); } try wrtr.writeAll("],\"waiting\":["); for (self.queu.items, 0..) |jobz, indx| { if (indx > 0) try wrtr.writeAll(","); try wrtr.writeAll("{\"id\":"); try std.json.Stringify.encodeJsonString(jobz.iden, .{}, wrtr); try wrtr.writeAll(",\"lock\":"); try std.json.Stringify.encodeJsonString(jobz.lock, .{}, wrtr); try wrtr.print(",\"retry\":{d}}}", .{jobz.atte}); } try wrtr.writeAll("]}"); }
pub fn jobzExec(self: *Sche, iozz: std.Io, jobz: *Jobz) bool { var resu = self.jobzRunz(iozz, jobz) catch |erro| blk: { if (!self.runz_warn.swap(true, .monotonic)) { std.debug.print("  warn: task '{s}' failed to run ({t})\n", .{ jobz.iden, erro }); } break :blk RunzResu{ .code = -1, .elap_msec = 0 }; }; resu.retr = jobz.atte; resu.catc = jobz.iszz_catc; const skip = jobz.chai and resu.code == CF.skip_code; if (skip) resu.code = 0; const abor = jobz.chai and self.aborTake(iozz, jobz.iden); if (resu.code != 0 and !abor and jobz.atte < jobz.retr and !self.stop.load(.acquire)) { jobz.atte += 1; const shif: u5 = @intCast(@min(jobz.atte - 1, 15)); const back: i64 = @min(@as(i64, CF.retr_base_msec) << shif, CF.retr_maxz_msec); jobz.notz_befo_msec = nowzMsec(iozz) + back; self.queuRequ(iozz, jobz); return true; } if (jobz.teez) |teez| ringSeal(iozz, teez, resu.code, resu.elap_msec); if (resu.code != 0 and !abor and !jobz.nozz_logz) self.failNoti(iozz, jobz, resu); if (self.mute.lock(iozz)) |_| { self.done.skipPush(jobz.iden, resu.code == 0, jobz.dept, skip); self.mute.unlock(iozz); } else |_| {} if (!jobz.nozz_logz) { self.fireLogz(iozz, jobz, resu) catch |erro| { if (!self.logz_warn.swap(true, .monotonic)) { std.debug.print("  warn: task log write failed ({t}) — tasks still fire\n", .{erro}); } }; } return false; }
pub fn jobzRunz(self: *Sche, iozz: std.Io, jobz: *const Jobz) !RunzResu { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const allo = aren.allocator(); var sink: std.Io.Writer.Discarding = .init(&.{}); const cwdz = if (jobz.cwdz.len > 0) jobz.cwdz else self.root; var envi: ?*std.process.Environ.Map = null; var envi_maps: std.process.Environ.Map = undefined; if (jobz.queu_file.len > 0) { envi_maps = conf.enviMap(allo) catch return error.EnvFailed; const base = if (jobz.queu_dirz.len > 0) jobz.queu_dirz else cwdz; const full = try std.fmt.allocPrint(allo, "{s}{c}{s}", .{ base, std.fs.path.sep, jobz.queu_file }); envi_maps.put("QUEUE_FILE", full) catch {}; envi_maps.put("CMDRUN_TASK_ID", jobz.iden) catch {}; envi = &envi_maps; } if (jobz.teez) |teez| if (jobz.atte > 0) { var rbuf: [64]u8 = undefined; if (std.fmt.bufPrint(&rbuf, "── retry {d} ──\n", .{jobz.atte})) |head| ringNote(iozz, teez, head) else |_| {} }; const star_msec = nowzMsec(iozz); const code = spaw.runz(allo, iozz, &sink.writer, &self.regz, .{ .cmdz = jobz.runz, .cwdz = cwdz, .shel = spaw.shelPars(jobz.shel), .jobz_iden = if (jobz.chai) jobz.iden else "", .envi = envi, .teez = jobz.teez, .time_msec = jobz.time_msec }, star_msec) catch |erro| return erro; return .{ .code = code, .elap_msec = nowzMsec(iozz) - star_msec }; }
pub fn fireLogz(self: *Sche, iozz: std.Io, jobz: *const Jobz, resu: RunzResu) !void { const iden = jobz.iden; var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const allo = aren.allocator(); const dirz = try logzDirz(allo, iozz); const full = try std.fmt.allocPrint(allo, "{s}{c}{s}.log", .{ dirz, std.fs.path.sep, iden }); var file = try std.Io.Dir.cwd().createFile(iozz, full, .{ .truncate = false, .read = true }); defer file.close(iozz); var endz = try file.length(iozz); if (endz >= CF.logz_maxz_byte) { file.close(iozz); logzRota(allo, iozz, full); file = try std.Io.Dir.cwd().createFile(iozz, full, .{ .truncate = false, .read = true }); endz = try file.length(iozz); } const nowz = time.localNow(); const tagz = if (resu.code == spaw.TIME_CODE) "  TIMEOUT" else if (resu.catc) "  CATCHUP" else ""; const line = if (resu.retr > 0) try std.fmt.allocPrint(allo, "{d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2}  exit:{d}  {d}ms  retry:{d}{s}  $ {s}\n", .{ nowz.year, nowz.month, nowz.day, nowz.hour, nowz.minute, nowz.second, resu.code, resu.elap_msec, resu.retr, tagz, jobz.runz }) else try std.fmt.allocPrint(allo, "{d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2}  exit:{d}  {d}ms{s}  $ {s}\n", .{ nowz.year, nowz.month, nowz.day, nowz.hour, nowz.minute, nowz.second, resu.code, resu.elap_msec, tagz, jobz.runz }); try file.writePositionalAll(iozz, line, endz); self.runzNote(iozz, iden, resu, nowz); }
pub fn failNoti(self: *Sche, iozz: std.Io, jobz: *const Jobz, resu: RunzResu) void { if (self.toas.load(.acquire) >= CF.toas_maxz) return; const mesg = std.fmt.allocPrint(self.gpaz, "exit {d} after {d}ms — {s}", .{ resu.code, resu.elap_msec, jobz.runz }) catch return; _ = self.toas.fetchAdd(1, .acq_rel); const thre = std.Thread.spawn(.{}, toasThre, .{ self, iozz, mesg }) catch { _ = self.toas.fetchSub(1, .acq_rel); self.gpaz.free(mesg); return; }; thre.detach(); }
pub fn toasThre(self: *Sche, iozz: std.Io, mesg: []const u8) void { defer { self.gpaz.free(mesg); _ = self.toas.fetchSub(1, .acq_rel); } var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const allo = aren.allocator(); var envi = conf.enviMap(allo) catch return; envi.put("CMDRUN_NT", "auto-task: task failed") catch return; envi.put("CMDRUN_NM", mesg) catch return; const argv: []const []const u8 = switch (@import("builtin").os.tag) { .windows => &.{ "powershell", "-NoProfile", "-NonInteractive", "-Command", CF.toas_wins }, .macos => &.{ "osascript", "-e", "display notification (system attribute \"CMDRUN_NM\") with title (system attribute \"CMDRUN_NT\")" }, else => &.{ "notify-send", "auto-task: task failed", mesg } }; var chil = spaw.chilSpaw(iozz, .{ .argv = argv, .environ_map = &envi, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore, .create_no_window = true }) catch return; _ = chil.wait(iozz) catch {}; }
pub fn workBusy(self: *Sche, iozz: std.Io) bool { self.queu_mute.lock(iozz) catch return false; defer self.queu_mute.unlock(iozz); return self.queu_work > 0; }
